// TestPlayUsesUrgentLane is the acceptance test for the play-priority wiring
// (eviction 3.2, design D4): the play closures ride the PREFERRED lane —
// packOnPlay and retryFailedPack enqueue through EnqueuePackUrgent (the
// composition's newPlayClosure wiring) — while the sweep's dispatch seam
// stays the plain EnqueuePack. A real enrich.Queue with its single worker
// pinned inside PackItem holds the state: the shared buffer saturates with
// background packs and the preferred lane stays free, so a play-initiated
// pack is accepted (queued=true, the 202 shape) while a sweep-initiated one
// meets the honest drop-on-full refusal of the full shared buffer. Releasing
// the pin proves the lane landing end to end: the urgent tasks dispatch
// ahead of the buffered backlog's head (the worker's non-blocking urgent
// receive before the shared range). No prod behavior changes beyond the lane
// choice: the drop-on-full contract, the deferred-enqueue WARN fallback, and
// every signature are untouched.
func TestPlayUsesUrgentLane(t *testing.T) {
	st, ctx := gateSeedStore(t, map[string]map[string]any{
		"it_bg":    gateStreamsDoc(gateFfOpen, "none", ""),     // background filler
		"it_play":  gateStreamsDoc(gateFfOpen, "none", ""),     // the pack-on-play item
		"it_retry": gateStreamsDoc(gateFfOpen, "failed", "n1"), // the retry item
	})

	var packMu sync.Mutex
	var packed []string // the streams-lane dispatch order, as PackItem saw it
	pinEntered := make(chan string, 1)
	release := make(chan struct{})
	var once sync.Once
	openPin := func() { once.Do(func() { close(release) }) }
	packItem := func(_ context.Context, itemID, _ string, _ map[string]any, _ []string) (pack.PackOutcome, error) {
		select {
		case pinEntered <- itemID:
		default:
		}
		<-release // the pin: nothing drains until the test says so
		packMu.Lock()
		packed = append(packed, itemID)
		packMu.Unlock()
		return pack.PackOutcome{Playlist: "index.m3u8", Nonce: "n-" + itemID}, nil
	}

	// The feeder's derivation walks the module registry: open the real one
	// over the same store (the queueTestStore precedent in internal/enrich).
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   magicCookieKey,
		MagicCookieValue: magicCookieValue,
	})
	q := enrich.NewQueue(enrich.Deps{Store: st, Modules: reg, Plugins: mgr, PackItem: packItem}, enrich.QueueConfig{Workers: 1})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("queue start: %v", err)
	}
	t.Cleanup(func() {
		openPin() // never leave the worker parked on a gate the test no longer owns
		q.Stop()
	})

	// Pin the worker: the first background pack is grabbed and parks inside
	// PackItem, so the shared buffer can saturate behind it.
	if err := q.EnqueuePack("it_bg"); err != nil {
		t.Fatalf("EnqueuePack it_bg: %v", err)
	}
	select {
	case got := <-pinEntered:
		if got != "it_bg" {
			t.Fatalf("worker pinned inside PackItem for %q, want it_bg", got)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("worker never reached PackItem")
	}

	// Saturate the shared buffer (Workers:1 locks its 16-slot capacity) with
	// background packs until the drop-on-full refusal answers.
	saturated := false
	for i := 0; i < 4*16; i++ {
		if err := q.EnqueuePack(fmt.Sprintf("bg%d", i)); err != nil {
			saturated = true
			break
		}
	}
	if !saturated {
		t.Fatal("shared buffer never saturated — every background pack was accepted")
	}

	// The sweep's seam (EnqueuePack — the method value newSweep carries)
	// lands in the shared lane: in this state it is honestly refused ...
	if err := q.EnqueuePack("it_sweep"); err == nil {
		t.Fatal("a sweep dispatch into the saturated shared buffer was accepted — want the drop-on-full refusal")
	}

	// ... while the play closures ride the preferred lane: both answer
	// queued=true (the 202 shape) with the shared buffer still full.
	queued, err := packOnPlay(ctx, st, q.EnqueuePackUrgent, mustRow(t, st, ctx, "it_play"), false)
	if !queued || err != nil {
		t.Fatalf("packOnPlay = (%v, %v), want (true, nil) — the preferred lane had room", queued, err)
	}
	queued, err = retryFailedPack(ctx, st, q.EnqueuePackUrgent, mustRow(t, st, ctx, "it_retry"), false)
	if !queued || err != nil {
		t.Fatalf("retryFailedPack = (%v, %v), want (true, nil) — the preferred lane had room", queued, err)
	}

	// The composition wiring itself: the Deps.Play closure (newPlayClosure
	// over EnqueuePackUrgent, exactly what main.go passes) enqueues through
	// the same preferred lane for both pack decisions.
	play := newPlayClosure(st, q.EnqueuePackUrgent, false, nil)
	if queued, err := play(ctx, "it_play", false, nil); !queued || err != nil {
		t.Fatalf("play(pack-on-play) = (%v, %v), want (true, nil)", queued, err)
	}
	if queued, err := play(ctx, "it_retry", true, nil); !queued || err != nil {
		t.Fatalf("play(retry) = (%v, %v), want (true, nil)", queued, err)
	}

	// Prove the lane landing: release the pin — all four urgent tasks
	// dispatch ahead of the shared backlog's head, in the urgent channel's
	// FIFO order (play, retry, play, retry — one per worker loop pass).
	openPin()
	want := []string{"it_bg", "it_play", "it_retry", "it_play", "it_retry"}
	awaitPacks(t, &packMu, &packed, len(want))
	packMu.Lock()
	defer packMu.Unlock()
	for i, id := range want {
		if packed[i] != id {
			t.Fatalf("dispatch order = %v, want %v — the play packs must jump the shared backlog", packed, want)
		}
	}
}

// awaitPacks polls until at least n streams dispatches have recorded, or
// fails after a bounded window (a stalled lane must fail loudly, not hang).
func awaitPacks(t *testing.T, mu *sync.Mutex, packed *[]string, n int) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		got := len(*packed)
		mu.Unlock()
		if got >= n {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	mu.Lock()
	defer mu.Unlock()
	t.Fatalf("packed = %d dispatches, want at least %d — the lane never drained", len(*packed), n)
}
